changeSet.sql:
CREATE TABLE topic_votes (
    id        UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    topic_id  UUID NOT NULL REFERENCES topics(id) ON DELETE CASCADE,
    user_id   UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    weight    SMALLINT NOT NULL,
    voted_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT topic_votes_weight_check CHECK (weight IN (-1, 1)),
    CONSTRAINT topic_votes_unique UNIQUE (topic_id, user_id)
);

CREATE INDEX idx_topic_votes_topic ON topic_votes(topic_id);
CREATE INDEX idx_topic_votes_user ON topic_votes(user_id);

rollback.sql:
DROP INDEX IF EXISTS idx_topic_votes_user;
DROP INDEX IF EXISTS idx_topic_votes_topic;
DROP TABLE IF EXISTS topic_votes;
